select name="charter[authorization_letter]" <?php echo $is_locked?'disabled':''; ?>><option value="Not Applicable" <?php echo selc($charter,'authorization_letter','Not Applicable'); ?>>Not Applicable</option><option value="Presented" <?php echo selc($charter,'authorization_letter','Presented'); ?>>Presented</option><option value="Required but Missing" <?php echo selc($charter,'authorization_letter','Required but Missing'); ?>>Required but Missing</option></select></div><div class="field"><label>Household Members</label><input type="number" min="1" name="household_members" value="<?php echo h($form['household_members'] ?? ''); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Dependents</label><input type="number" min="0" name="dependents" value="<?php echo h($form['dependents'] ?? ''); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Monthly Income</label><input type="number" min="0" step="0.01" name="monthly_income" value="<?php echo h($form['monthly_income'] ?? '0'); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Source of Income</label><input name="income_source" value="<?php echo h($form['income_source'] ?? ''); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Client Category</label><input name="beneficiary_type" value="<?php echo h($form['beneficiary_type'] ?? $priorityText); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Assistance Requested</label><input name="assistance_reason" value="<?php echo h($form['assistance_reason'] ?? $program); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>CrIMS / Frequency Check</label><select name="matches_masterlist" <?php echo $is_locked?'disabled':''; ?> required><option value="Yes" <?php echo s($form,'matches_masterlist','Yes'); ?>>Eligible based on frequency / no disqualifying record</option><option value="No" <?php echo s($form,'matches_masterlist','No'); ?>>