ed_cash_amount" value="<?php echo h($form['approved_cash_amount'] ?? '0'); ?>" <?php echo $is_locked?'disabled':''; ?>></div><div class="field"><label>Already Received Assistance?</label><select name="already_received_payout" <?php echo $is_locked?'disabled':''; ?>><option value="No" <?php echo s($form,'already_received_payout','No'); ?>>No</option><option value="Yes" <?php echo s($form,'already_received_payout','Yes'); ?>>Yes</option></select></div><div class="field"><label>Receiving Other Assistance?</label><select name="receiving_other_assistance" <?php echo $is_locked?'disabled':''; ?>><option value="No" <?php echo s($form,'receiving_other_assistance','No'); ?>>No</option><option value="Yes" <?php echo s($form,'receiving_other_assistance','Yes'); ?>>Yes</option></select></div><div class="field full"><label>Social Worker Assessment / Justification</label><textarea name="charter[swo_assessment]" <?php echo $is_locked?'disabled':''; ?>><?php echo cv($charter,'swo_assessment'); ?></textarea></div><div class="field full"><label>Remarks for GIS / CE / GL / Compliance Slip / Referral</label><textarea name="charter[ce_remarks]" <?php echo $is_locked?'disabled':''; ?>><?php echo cv($charter,'ce_remarks'); ?></textarea></div></div>
